# ---------- /api/uploads/embed ----------

class TestEmbedParser:
    def test_youtube_watch(self, member_headers):
        r = requests.post(f"{BASE_URL}/api/uploads/embed", headers=member_headers,
                          json={"url": "https://www.youtube.com/watch?v=dQw4w9WgXcQ"})
        assert r.status_code == 200, r.text
        body = r.json()
        assert body["provider"] == "youtube"
        assert body["video_id"] == "dQw4w9WgXcQ"
        assert "embed" in body["embed_url"]
        assert body.get("thumbnail_url")

    def test_youtube_short_url(self, member_headers):
        r = requests.post(f"{BASE_URL}/api/uploads/embed", headers=member_headers,
                          json={"url": "https://youtu.be/dQw4w9WgXcQ"})
        assert r.status_code == 200
        assert r.json()["video_id"] == "dQw4w9WgXcQ"

    def test_youtube_shorts(self, member_headers):
        r = requests.post(f"{BASE_URL}/api/uploads/embed", headers=member_headers,
                          json={"url": "https://www.youtube.com/shorts/dQw4w9WgXcQ"})
        assert r.status_code == 200
        assert r.json()["video_id"] == "dQw4w9WgXcQ"

    def test_vimeo(self, member_headers):
        r = requests.post(f"{BASE_URL}/api/uploads/embed", headers=member_headers,
                          json={"url": "https://vimeo.com/123456789"})
        assert r.status_code == 200
        body = r.json()
        assert body["provider"] == "vimeo"
        assert body["video_id"] == "123456789"
        assert "player.vimeo.com" in body["embed_url"]

    def test_unsupported_url(self, member_headers):
        r = requests.post(f"{BASE_URL}/api/uploads/embed", headers=member_headers,
                          json={"url": "https://example.com/cool-video"})
        assert r.status_code == 400


# ---------- /api/posts media composition ----------

def _upload_image(headers):
    import tempfile
    with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as t:
        tmp = t.name
    subprocess.run(["ffmpeg", "-y", "-f", "lavfi", "-i", "color=c=blue:s=10x10:d=1",
                    "-frames:v", "1", tmp, "-loglevel", "error"], check=True)
    with open(tmp, "rb") as f:
        data = f.read()
    os.unlink(tmp)
    files = {"file": ("a.jpg", data, "image/jpeg")}
    r = requests.post(f"{BASE_URL}/api/uploads", headers=headers, files=files)
    assert r.status_code == 200, r.text
    return r.json()["path"]


def _upload_video(headers):
    with open(SHORT_MP4, "rb") as f:
        data = f.read()
    files = {"file": ("v.mp4", data, "video/mp4")}
    r = requests.post(f"{BASE_URL}/api/uploads", headers=headers, files=files)
    assert r.status_code == 200, r.text
    return r.json()


def _upload_audio(headers):
    with open(AUDIO_MP3, "rb") as f:
        data = f.read()
    files = {"file": ("a.mp3", data, "audio/mpeg")}
    r = requests.post(f"{BASE_URL}/api/uploads", headers=headers, files=files)
    assert r.status_code == 200, r.text
    return r.json()


class TestPostsMedia:
    def test_short_post_with_mixed_media(self, member_headers):
        img1 = _upload_image(member_headers)
        img2 = _upload_image(member_headers)
        vid = _upload_video(member_headers)
        aud = _upload_audio(member_headers)
        payload = {
            "kind": "post",
            "text": "Post with media gallery",
            "media": [
                {"kind": "image", "path": img1},
                {"kind": "image", "path": img2},
                {"kind": "video", "path": vid["path"], "thumbnail_path": vid.get("thumbnail_path"),
                 "duration_s": vid["duration_s"], "width": vid["width"], "height": vid["height"]},
                {"kind": "audio", "path": aud["path"], "duration_s": aud["duration_s"]},
            ],
        }
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 200, r.text
        pid = r.json()["post_id"]
        # Verify via mine feed
        mine = requests.get(f"{BASE_URL}/api/posts/mine", headers=member_headers)
        assert mine.status_code == 200
        items = mine.json()["items"]
        post = next((p for p in items if p["post_id"] == pid), None)
        assert post is not None
        assert len(post["media"]) == 4
        kinds = [m["kind"] for m in post["media"]]
        assert kinds.count("image") == 2
        assert "video" in kinds and "audio" in kinds

    def test_short_post_5_images_rejected(self, member_headers):
        img = _upload_image(member_headers)
        payload = {
            "kind": "post",
            "text": "Too many images",
            "media": [{"kind": "image", "path": img} for _ in range(5)],
        }
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 422, r.text

    def test_short_post_two_videos_rejected(self, member_headers):
        v1 = _upload_video(member_headers)
        v2 = _upload_video(member_headers)
        payload = {
            "kind": "post",
            "text": "Two videos",
            "media": [
                {"kind": "video", "path": v1["path"]},
                {"kind": "video", "path": v2["path"]},
            ],
        }
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 422

    def test_video_plus_embed_rejected(self, member_headers):
        v = _upload_video(member_headers)
        payload = {
            "kind": "post",
            "text": "Video + embed",
            "media": [
                {"kind": "video", "path": v["path"]},
                {"kind": "embed", "provider": "youtube", "embed_url": "https://www.youtube.com/embed/abc12345"},
            ],
        }
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 422

    def test_essay_with_media(self, member_headers):
        img = _upload_image(member_headers)
        body = "x " * 200
        payload = {
            "kind": "essay",
            "title": "Essay with media",
            "text": body,
            "media": [{"kind": "image", "path": img}],
        }
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 200, r.text
        pid = r.json()["post_id"]
        # essay detail
        ed = requests.get(f"{BASE_URL}/api/essays/{pid}", headers=member_headers)
        assert ed.status_code == 200
        body_json = ed.json()
        assert len(body_json["media"]) == 1
        assert body_json["media"][0]["kind"] == "image"

    def test_essay_too_short_rejected(self, member_headers):
        payload = {"kind": "essay", "title": "Hi", "text": "too short"}
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 422

    def test_essay_missing_title_rejected(self, member_headers):
        payload = {"kind": "essay", "text": "x" * 200}
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 422


# ---------- legacy back-compat ----------

class TestLegacyBackCompat:
    def test_legacy_image_path_surfaces_in_media(self, member_headers):
        img = _upload_image(member_headers)
        # Old-style payload using only image_path
        payload = {"kind": "post", "text": "legacy", "image_path": img}
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers, json=payload)
        assert r.status_code == 200, r.text
        pid = r.json()["post_id"]
        mine = requests.get(f"{BASE_URL}/api/posts/mine", headers=member_headers)
        post = next(p for p in mine.json()["items"] if p["post_id"] == pid)
        assert post["media"] and post["media"][0]["kind"] == "image"
        assert post["media"][0]["path"] == img


# ---------- drafts ----------

class TestDraftMedia:
    def test_draft_persists_media(self, member_headers):
        img = _upload_image(member_headers)
        payload = {"kind": "post", "text": "draft text",
                   "media": [{"kind": "image", "path": img}]}
        r = requests.put(f"{BASE_URL}/api/drafts/mine", headers=member_headers, json=payload)
        assert r.status_code == 200, r.text
        g = requests.get(f"{BASE_URL}/api/drafts/mine", headers=member_headers)
        assert g.status_code == 200
        d = g.json()
        assert d.get("media") and d["media"][0]["kind"] == "image"
        # cleanup
        requests.delete(f"{BASE_URL}/api/drafts/mine", headers=member_headers)


# ---------- feeds ----------

class TestFeeds:
    def test_public_feed_returns_media(self, member_headers):
        img = _upload_image(member_headers)
        r = requests.post(f"{BASE_URL}/api/posts", headers=member_headers,
                          json={"kind": "post", "text": "feed media", "media": [{"kind": "image", "path": img}]})
        assert r.status_code == 200
        pub = requests.get(f"{BASE_URL}/api/posts/public")
        assert pub.status_code == 200
        items = pub.json()["items"]
        # Just verify all returned posts include a media list
        for it in items[:10]:
            assert "media" in it
